/**
 * A-B 循環播放插件
 *
 * 在進度條上提供範圍選擇器，讓用戶選擇播放範圍
 * 播放到 B 點時自動跳回 A 點
 */

import type { MpvPlugin, PluginInstance } from '../../core/types/plugin';
import type { MpvVideoElement } from '../../renderer/ui/MpvVideoElement';
import styles from './styles.css?inline';

/**
 * A-B Loop 插件配置
 */
export interface ABLoopPluginOptions {
    /** 邊緣吸附閾值（百分比），默認 0.02 */
    snapThreshold?: number;
    /** A-B 點最小間隔（秒），默認 0.1 */
    minRangeDuration?: number;
    /** 是否自動啟用循環模式 */
    autoEnableLoop?: boolean;
}

/**
 * A-B Loop 插件定義
 */
export const ABLoopPlugin: MpvPlugin<ABLoopPluginOptions> = {
    name: 'abLoop',
    version: '1.0.0',
    dependencies: ['progress'],
    styles,

    install(player, options = {}) {
        return new ABLoopManager(player, {
            snapThreshold: options.snapThreshold ?? 0.02,
            minRangeDuration: options.minRangeDuration ?? 0.1,
            autoEnableLoop: options.autoEnableLoop ?? true,
        });
    },
};

/**
 * A-B Loop 管理器
 */
export class ABLoopManager implements PluginInstance {
    readonly name = 'abLoop';

    private player: MpvVideoElement;
    private options: Required<ABLoopPluginOptions>;

    // 狀態
    private _loopStart: number = 0;
    private _loopEnd: number = 0; // 0 表示使用 duration
    private _enabled: boolean = true;
    private _isDragging: boolean = false; // 拖拽中暫停 loop 邏輯

    // DOM 元素
    private containerEl: HTMLElement | null = null;
    private rangeBar: HTMLElement | null = null;
    private handleA: HTMLElement | null = null;
    private handleB: HTMLElement | null = null;

    // 事件處理器
    private timeupdateHandler: (() => void) | null = null;

    constructor(player: MpvVideoElement, options: Required<ABLoopPluginOptions>) {
        this.player = player;
        this.options = options;

        // 等待 controlBar 插件準備好後初始化
        this.initialize();
    }

    private initialize(): void {
        // 創建 UI
        this.createUI();

        // 監聽 timeupdate 實現循環
        this.timeupdateHandler = () => {
            // 拖拽中不執行 loop 邏輯，避免預覽時跳回 A 點
            if (!this._enabled || this._isDragging) return;

            const currentTime = this.player.currentTime;
            const endTime = this.effectiveLoopEnd;

            // 檢查是否到達 B 點（有自定義範圍時才處理）
            if (this._loopStart > 0 || this._loopEnd > 0) {
                if (currentTime >= endTime - 0.05) {
                    if (this.player.loop) {
                        // loop 模式：跳回 A 點
                        this.player.currentTime = this._loopStart;
                    } else {
                        // 非 loop 模式：暫停在 B 點
                        this.player.pause();
                    }
                }
            }
        };
        this.player.addEventListener('timeupdate', this.timeupdateHandler);
    }

    private createUI(): void {
        // 獲取進度條元素
        const shadowRoot = this.player.shadowRoot;
        if (!shadowRoot) return;

        const progressBar = shadowRoot.querySelector('.mpv-progress-bar, .vp-progress-bar');
        if (!progressBar) return;

        // 創建容器
        this.containerEl = document.createElement('div');
        this.containerEl.className = 'mpv-abloop-container';

        // 範圍進度條
        this.rangeBar = document.createElement('div');
        this.rangeBar.className = 'mpv-abloop-range';

        // A 點手柄
        this.handleA = document.createElement('div');
        this.handleA.className = 'mpv-abloop-handle mpv-abloop-handle-a';

        // B 點手柄
        this.handleB = document.createElement('div');
        this.handleB.className = 'mpv-abloop-handle mpv-abloop-handle-b';

        // 組裝
        this.containerEl.appendChild(this.rangeBar);
        this.containerEl.appendChild(this.handleA);
        this.containerEl.appendChild(this.handleB);
        progressBar.appendChild(this.containerEl);

        // 綁定拖拽事件
        this.bindDragEvents();
    }

    private bindDragEvents(): void {
        if (!this.handleA || !this.handleB) return;

        let dragging: 'a' | 'b' | null = null;
        let savedTooltipEnabled = true; // 保存拖拽前的 tooltip 狀態

        const onMouseDown = (handle: 'a' | 'b') => (e: MouseEvent) => {
            e.stopPropagation();
            dragging = handle;
            this._isDragging = true; // 暫停 loop 邏輯
            (handle === 'a' ? this.handleA : this.handleB)?.classList.add('dragging');

            // 啟用 scrubbing 模式（高效能 seek）
            this.player.setScrubbing(true);

            // 暫時禁用 tooltip（保存原始值以便恢復）
            savedTooltipEnabled = this.player.tooltipEnabled;
            this.player.tooltipEnabled = false;

            if (this.options.autoEnableLoop && !this.player.loop) {
                this.player.loop = true;
            }
        };

        const onMouseMove = (e: MouseEvent) => {
            if (!dragging) return;

            const progressBar = this.containerEl?.parentElement;
            if (!progressBar) return;

            const rect = progressBar.getBoundingClientRect();
            const percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
            const duration = this.player.duration;
            const time = percent * duration;

            if (dragging === 'a') {
                const maxTime = this.effectiveLoopEnd - this.options.minRangeDuration;
                this._loopStart = Math.max(0, Math.min(time, maxTime));
                // 邊緣吸附
                if (percent <= this.options.snapThreshold) {
                    this._loopStart = 0;
                }
            } else {
                const minTime = this._loopStart + this.options.minRangeDuration;
                if (percent >= 1 - this.options.snapThreshold) {
                    this._loopEnd = 0;
                } else {
                    this._loopEnd = Math.max(minTime, Math.min(time, duration));
                }
            }

            this.updateUI();
            this.player.currentTime = dragging === 'a' ? this._loopStart : this.effectiveLoopEnd;
        };

        const onMouseUp = () => {
            if (dragging) {
                (dragging === 'a' ? this.handleA : this.handleB)?.classList.remove('dragging');
                dragging = null;
                this._isDragging = false; // 恢復 loop 邏輯

                // 結束 scrubbing 模式
                this.player.setScrubbing(false);

                // 恢復 tooltip 狀態
                this.player.tooltipEnabled = savedTooltipEnabled;
            }
        };

        // 雙擊重置
        const onDblClickA = (e: MouseEvent) => {
            e.stopPropagation();
            this.resetA();
        };

        const onDblClickB = (e: MouseEvent) => {
            e.stopPropagation();
            this.resetB();
        };

        this.handleA.addEventListener('mousedown', onMouseDown('a'));
        this.handleB.addEventListener('mousedown', onMouseDown('b'));
        this.handleA.addEventListener('dblclick', onDblClickA);
        this.handleB.addEventListener('dblclick', onDblClickB);
        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
    }

    /** 重置 A 點到起始位置 */
    resetA(): void {
        this._loopStart = 0;
        this.updateUI();
    }

    /** 重置 B 點到結束位置 */
    resetB(): void {
        this._loopEnd = 0; // 0 表示 duration
        this.updateUI();
    }

    private updateUI(): void {
        if (!this.handleA || !this.handleB || !this.rangeBar) return;

        const duration = this.player.duration;
        if (!duration) return;

        const percentA = (this._loopStart / duration) * 100;
        const percentB = (this.effectiveLoopEnd / duration) * 100;

        this.handleA.style.left = `${percentA}%`;
        this.handleB.style.left = `${percentB}%`;
        this.rangeBar.style.left = `${percentA}%`;
        this.rangeBar.style.width = `${percentB - percentA}%`;
    }

    // ===== 公開 API =====

    /** A 點時間（秒） */
    get loopStart(): number {
        return this._loopStart;
    }

    set loopStart(value: number) {
        this._loopStart = Math.max(0, Math.min(value, this.effectiveLoopEnd));
        this.updateUI();
    }

    /** B 點時間（秒），0 表示視頻結尾 */
    get loopEnd(): number {
        return this._loopEnd;
    }

    set loopEnd(value: number) {
        const duration = this.player.duration;
        if (value === 0 || value >= duration) {
            this._loopEnd = 0;
        } else {
            this._loopEnd = Math.max(this._loopStart, Math.min(value, duration));
        }
        this.updateUI();
    }

    /** 實際的結束時間 */
    get effectiveLoopEnd(): number {
        return this._loopEnd === 0 ? this.player.duration : this._loopEnd;
    }

    /** 重置範圍 */
    reset(): void {
        this._loopStart = 0;
        this._loopEnd = 0;
        this.updateUI();
    }

    /** 設置 A 點為當前時間 */
    setAToCurrentTime(): void {
        this.loopStart = this.player.currentTime;
    }

    /** 設置 B 點為當前時間 */
    setBToCurrentTime(): void {
        this.loopEnd = this.player.currentTime;
    }

    enable(): void {
        this._enabled = true;
    }

    disable(): void {
        this._enabled = false;
    }

    get enabled(): boolean {
        return this._enabled;
    }

    destroy(): void {
        if (this.timeupdateHandler) {
            this.player.removeEventListener('timeupdate', this.timeupdateHandler);
        }
        this.containerEl?.remove();
    }
}

